describe("extraUnsealPasswords", () => {
  const oldPassword = "old-password-0123456789abcdefghijk";
  const extraConfig: SessionConfig = {
    name: "h3-extra",
    password: sessionConfig.password,
    extraUnsealPasswords: [oldPassword],
    generateId: () => "extra-new",
  };

  const sealFor = (
    password: string,
    extra: Record<string, unknown> = {},
    options = sealDefaults,
  ) =>
    seal({ id: "old-1", createdAt: Date.now(), data: { foo: "old" }, ...extra }, password, options);

  // Value of the last `Set-Cookie` named `name`, still sealed
  const sealedCookie = (res: Response, name: string) => {
    const header = res.headers.getSetCookie().findLast((c) => c.startsWith(`${name}=`))!;
    return decodeURIComponent(header.slice(name.length + 1).split(";")[0]);
  };

  it("opens a session sealed with an extra password (RF-01)", async () => {
    t.app.get("/extra-read", async (event) => {
      const session = await getSession(event, extraConfig);
      return { id: session.id, data: session.data };
    });
    const sealed = await sealFor(oldPassword);
    const res = await t.fetch("/extra-read", { headers: { Cookie: `h3-extra=${sealed}` } });
    expect(await res.json()).toEqual({ id: "old-1", data: { foo: "old" } });
  });

  it("seals with the current password only (RF-02)", async () => {
    t.app.get("/extra-write", async (event) => {
      await updateSession(event, extraConfig, { foo: "new" });
      return { ok: true };
    });
    const res = await t.fetch("/extra-write");
    const sealed = sealedCookie(res, "h3-extra");
    expect(await unseal(sealed, sessionConfig.password, sealDefaults)).toMatchObject({
      data: { foo: "new" },
    });
    await expect(unseal(sealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("reseals a session opened by an extra password (RF-03)", async () => {
    t.app.get("/extra-reseal", async (event) => {
      const session = await getSession(event, extraConfig);
      return { id: session.id, data: session.data };
    });
    const sealed = await sealFor(oldPassword);
    const res = await t.fetch("/extra-reseal", { headers: { Cookie: `h3-extra=${sealed}` } });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    const resealed = sealedCookie(res, "h3-extra");
    expect(await unseal(resealed, sessionConfig.password, sealDefaults)).toMatchObject({
      id: "old-1",
      data: { foo: "old" },
    });
    await expect(unseal(resealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("does not reseal a session sealed with the current password (RF-03)", async () => {
    t.app.get("/extra-current", async (event) => {
      const session = await getSession(event, extraConfig);
      return { id: session.id, data: session.data };
    });
    const sealed = await sealFor(sessionConfig.password);
    const res = await t.fetch("/extra-current", { headers: { Cookie: `h3-extra=${sealed}` } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
    expect(await res.json()).toEqual({ id: "old-1", data: { foo: "old" } });
  });

  it("treats a session sealed with another password as new without extras (RF-04)", async () => {
    const sealed = await sealFor(oldPassword);
    const baseConfig: SessionConfig = {
      name: "h3-extra",
      password: sessionConfig.password,
      generateId: () => "fresh",
    };
    t.app.get("/extra-none", async (event) => {
      const session = await getSession(event, baseConfig);
      return { id: session.id, data: session.data };
    });
    t.app.get("/extra-empty", async (event) => {
      const session = await getSession(event, { ...baseConfig, extraUnsealPasswords: [] });
      return { id: session.id, data: session.data };
    });
    for (const path of ["/extra-none", "/extra-empty"]) {
      const res = await t.fetch(path, { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toEqual({ id: "fresh", data: {} });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    }
  });

  it("expires by maxAge even when an extra password opens the seal (RF-05)", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const sealed = await sealFor(oldPassword, { createdAt: t0 }, { ...sealDefaults, ttl: 0 });
      vi.setSystemTime(t0 + 61_000);
      const config: SessionConfig = { ...extraConfig, maxAge: 60 };
      await expect(unsealSession({} as HTTPEvent, config, sealed)).rejects.toThrow(
        "Session expired!",
      );
    } finally {
      vi.useRealTimers();
    }
  });

  it("unseals and reseals a legacy seal with an extra password (RF-06)", async () => {
    t.app.get("/extra-legacy", async (event) => {
      const session = await getSession(event, extraConfig);
      return { id: session.id, data: session.data };
    });
    const legacy = await sealFor(oldPassword, {}, {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    });
    const res = await t.fetch("/extra-legacy", { headers: { Cookie: `h3-extra=${legacy}` } });
    expect(await res.json()).toEqual({ id: "old-1", data: { foo: "old" } });
    const resealed = sealedCookie(res, "h3-extra");
    expect(await unseal(resealed, sessionConfig.password, sealDefaults)).toMatchObject({
      id: "old-1",
    });
  });

  it("does not open a legacy seal with an extra password when legacySealFallback is false (RF-06)", async () => {
    t.app.get("/extra-legacy-off", async (event) => {
      const session = await getSession(event, { ...extraConfig, legacySealFallback: false });
      return { id: session.id };
    });
    const legacy = await sealFor(oldPassword, {}, {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    });
    const res = await t.fetch("/extra-legacy-off", {
      headers: { Cookie: `h3-extra=${legacy}` },
    });
    expect(await res.json()).toEqual({ id: "extra-new" });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("rejects invalid extra passwords before reading the session (RF-07)", async () => {
    let extras: unknown;
    t.app.get("/extra-validate", async (event) => {
      try {
        await getSession(event, { ...extraConfig, extraUnsealPasswords: extras as string[] });
        return { error: null };
      } catch (error) {
        return { error: (error as Error).message };
      }
    });
    const sealed = await sealFor(oldPassword);
    for (const invalid of [["curta"], [""], "não é array"]) {
      extras = invalid;
      const res = await t.fetch("/extra-validate", { headers: { Cookie: `h3-extra=${sealed}` } });
      const { error } = await res.json();
      expect(error).toContain("extraUnsealPasswords");
      expect(error).not.toContain("curta");
    }
    expect(t.errors).toHaveLength(0);
  });

  it("useSession also rejects invalid extra passwords (RF-07)", async () => {
    t.app.get("/extra-use", async (event) => {
      try {
        await useSession(event, { ...extraConfig, extraUnsealPasswords: ["curta"] });
        return { error: null };
      } catch (error) {
        return { error: (error as Error).message };
      }
    });
    const sealed = await sealFor(oldPassword);
    const res = await t.fetch("/extra-use", { headers: { Cookie: `h3-extra=${sealed}` } });
    expect((await res.json()).error).toContain("extraUnsealPasswords[0]");
  });

  it("opens a session from the session header with an extra password (RF-08)", async () => {
    t.app.get("/extra-header", async (event) => {
      const session = await getSession(event, extraConfig);
      return { id: session.id, data: session.data };
    });
    const sealed = await sealFor(oldPassword);
    const res = await t.fetch("/extra-header", { headers: { "x-h3-extra-session": sealed } });
    expect(await res.json()).toEqual({ id: "old-1", data: { foo: "old" } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("does not open an expired session from the header with an extra password (RF-05, RF-08)", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      t.app.get("/extra-header-expired", async (event) => {
        const session = await getSession(event, { ...extraConfig, maxAge: 60 });
        return { id: session.id };
      });
      const sealed = await sealFor(
        oldPassword,
        { createdAt: t0 - 120_000 },
        { ...sealDefaults, ttl: 0 },
      );
      const res = await t.fetch("/extra-header-expired", {
        headers: { "x-h3-extra-session": sealed },
      });
      expect(await res.json()).toEqual({ id: "extra-new" });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    } finally {
      vi.useRealTimers();
    }
  });
});

